package io.invenlio;
import java.sql.DriverManager;import java.util.UUID;import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.testcontainers.junit.jupiter.*;import org.testcontainers.postgresql.PostgreSQLContainer;import static org.assertj.core.api.Assertions.assertThat;
@Testcontainers class V11MigrationIntegrationTest{@Container static final PostgreSQLContainer DB=new PostgreSQLContainer("postgres:17.6-alpine");
 @Test void upgradeFromV10ToV11PreservesExistingDataAndAddsSalesSchema()throws Exception{String schema="upgrade_"+UUID.randomUUID().toString().replace("-","");try(var c=DriverManager.getConnection(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());var s=c.createStatement()){s.execute("CREATE SCHEMA "+schema);}Flyway.configure().dataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword()).schemas(schema).defaultSchema(schema).target("10").load().migrate();UUID tenant=UUID.randomUUID();try(var c=DriverManager.getConnection(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());var s=c.createStatement()){s.execute("SET search_path TO "+schema);s.execute("INSERT INTO organizations(id,name,slug,status,default_locale,default_timezone,default_currency,created_at,updated_at,version)VALUES('"+tenant+"','Upgrade','sales-upgrade','ACTIVE','en','UTC','EUR',now(),now(),0)");}Flyway latest=Flyway.configure().dataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword()).schemas(schema).defaultSchema(schema).load();latest.migrate();assertThat(latest.info().current().getVersion().getVersion()).isEqualTo("12");try(var c=DriverManager.getConnection(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());var s=c.createStatement()){s.execute("SET search_path TO "+schema);try(var r=s.executeQuery("SELECT count(*) FROM organizations WHERE id='"+tenant+"'")){r.next();assertThat(r.getInt(1)).isOne();}try(var r=s.executeQuery("SELECT count(*) FROM customers")){r.next();assertThat(r.getInt(1)).isZero();}try(var r=s.executeQuery("SELECT count(*) FROM sales_orders")){r.next();assertThat(r.getInt(1)).isZero();}}}
}
